-- Stage 3 rationalised user-facing audit catalogue.
-- Preserves all technical result rows and stores only configuration/mappings plus a compact per-run group snapshot.

begin;

create table public.audit_user_facing_groups (
  id text primary key,
  name text not null,
  category text not null check (category in ('SEO','Accessibility','Performance','Security','Technical','AI & Crawler Readiness')),
  subcategory text not null,
  presentation_role text not null,
  outcome_policy text not null,
  failure_severity text not null,
  weight numeric(8,3) not null default 0 check (weight >= 0),
  authoritative_reference text,
  lifecycle public.check_lifecycle not null default 'active',
  enabled_by_default boolean not null default true,
  configuration_version integer not null default 1 check (configuration_version > 0),
  sort_order integer not null check (sort_order > 0),
  changed_by uuid references auth.users on delete set null,
  changed_at timestamptz not null default now()
);

create table public.audit_user_facing_group_checks (
  group_id text not null references public.audit_user_facing_groups(id) on delete cascade,
  check_id text not null references public.audit_check_definitions(id) on delete restrict,
  presentation_action text not null,
  lifecycle public.check_lifecycle not null default 'active',
  enabled_by_default boolean not null default true,
  sort_order integer not null check (sort_order > 0),
  changed_by uuid references auth.users on delete set null,
  changed_at timestamptz not null default now(),
  primary key (group_id, check_id),
  unique (check_id)
);

create index audit_user_facing_groups_availability_idx on public.audit_user_facing_groups(lifecycle, enabled_by_default, sort_order);
create index audit_user_facing_group_checks_availability_idx on public.audit_user_facing_group_checks(lifecycle, enabled_by_default, group_id, sort_order);

create table public.audit_catalogue_package_availability (
  target_kind text not null check (target_kind in ('technical_check','user_facing_group')),
  target_id text not null,
  entitlement text not null,
  enabled boolean not null,
  changed_by uuid references auth.users on delete set null,
  changed_at timestamptz not null default now(),
  primary key (target_kind, target_id, entitlement)
);

create table public.audit_catalogue_account_availability (
  target_kind text not null check (target_kind in ('technical_check','user_facing_group')),
  target_id text not null,
  account_id uuid not null references public.accounts(id) on delete cascade,
  enabled boolean not null,
  changed_by uuid references auth.users on delete set null,
  changed_at timestamptz not null default now(),
  primary key (target_kind, target_id, account_id)
);

create index audit_catalogue_package_entitlement_idx on public.audit_catalogue_package_availability(entitlement, target_kind, target_id);
create index audit_catalogue_account_account_idx on public.audit_catalogue_account_availability(account_id, target_kind, target_id);

alter table public.audit_user_facing_groups enable row level security;
alter table public.audit_user_facing_group_checks enable row level security;
alter table public.audit_catalogue_package_availability enable row level security;
alter table public.audit_catalogue_account_availability enable row level security;
revoke all on public.audit_user_facing_groups from anon, authenticated;
revoke all on public.audit_user_facing_group_checks from anon, authenticated;

revoke all on public.audit_catalogue_package_availability from anon, authenticated;
revoke all on public.audit_catalogue_account_availability from anon, authenticated;

alter table public.audit_runs add column user_facing_snapshot jsonb not null default '[]'::jsonb;


do $$
begin
  if (select count(*) from public.audit_check_definitions) >= 306 then
  end if;
end $$;

comment on table public.audit_user_facing_groups is 'Stable Stage 3 user-facing audit group definitions. Availability is configurable for future SuperAdmin controls.';
comment on table public.audit_user_facing_group_checks is 'Mapping from retained technical checks to rationalised user-facing groups. Disabled mappings are excluded from execution and scoring.';
comment on table public.audit_catalogue_package_availability is 'Optional package-level availability overrides. Absence preserves the target default.';
comment on table public.audit_catalogue_account_availability is 'Optional account-level availability overrides applied after package defaults.';
comment on column public.audit_runs.user_facing_snapshot is 'Compact effective user-facing grouping snapshot for this run; evidence remains in technical audit_results rows.';

values ('20261004133552', 'stage3_user_facing_audit_groups', 'self')
on conflict (version) do nothing;

commit;
